B.a0b=new A.hO("\uc5b4\ub5a4 \uc77c\uc0c1\uc5d0 \uc4f8 \ucc28\uc778\uc9c0 \uc815\ud574\uc694","\ucd9c\ud1f4\uadfc \uac70\ub9ac, \uc8fc\ub85c \ud0c0\ub294 \uc778\uc6d0, \uc8fc\ucc28 \ud658\uacbd\ubd80\ud130 \uc0dd\uac01\ud574 \ubcf4\uc138\uc694. \ucc28 \ud06c\uae30\uc640 \uc5f0\uac04 \uc8fc\ud589\uac70\ub9ac\ub97c \uc815\ud55c \ub4a4 \uac10\ub2f9\ud560 \uc218 \uc788\ub294 \uc6d4 \uc608\uc0b0\uc744 \uc7a1\uc73c\uba74 \uc120\ud0dd \ubc94\uc704\ub97c \uc904\uc77c \uc218 \uc788\uc5b4\uc694.","\uccab\ucc28! \uc608\uc05c \uac83\ub3c4 \uc88b\uc9c0\ub9cc \ub0b4 \uc77c\uc0c1\uc5d0 \ub9de\uc544\uc57c\uaca0\uc9c0?","\ucd9c\ud1f4\uadfc \uac70\ub9ac, \ud0d1\uc2b9 \uc778\uc6d0, \uc8fc\ucc28 \ud658\uacbd\ubd80\ud130 \uc0dd\uac01\ud574 \ubcf4\uc138\uc694.")
B.a06=new A.hO("\uc120\ub0a9\uae08\uacfc \ubcf4\uc99d\uae08\uc740 \ub2e4\ub978 \ub3c8\uc774\uc5d0\uc694","\uc120\ub0a9\uae08\uc740 \ub300\uc5ec\ub8cc \uc77c\ubd80\ub97c \ubbf8\ub9ac \ub0b4\ub294 \ub3c8\uc73c\ub85c, \ub9cc\uae30\uc5d0 \ub3cc\ub824\ubc1b\ub294 \ubcf4\uc99d\uae08\uacfc \ub2ec\ub77c\uc694. \uc120\ub0a9\uae08 0\uc6d0 \uc870\uac74\uc774 \uc788\uc5b4\ub3c4 \uc2ec\uc0ac\uc5d0 \ub530\ub77c \ubcf4\uc99d\uae08 \ub4f1\uc774 \ud544\uc694\ud560 \uc218 \uc788\uc5b4\uc694. \uc6d4 \ub0a9\uc785\ub8cc\uc5d0 \uc8fc\uc720\xb7\ucda9\uc804\ube44, \uc8fc\ucc28\ube44, \ud1b5\ud589\ub8cc\ub3c4 \ub354\ud574 \uc608\uc0b0\uc744 \ubcf4\uc138\uc694.","\ucc98\uc74c \ub0bc \ub3c8\uacfc \ub9e4\ub2ec \uc4f8 \ub3c8\uc744 \ub098\ub220 \uc801\uc5b4\ubcf4\uc790.","\uc120\ub0a9\uae08 0\uc6d0 \uc870\uac74\uc774\uc5b4\ub3c4 \uc2ec\uc0ac\uc5d0 \ub530\ub77c \ubcf4\uc99d\uae08 \ub4f1\uc774 \ud544\uc694\ud560 \uc218 \uc788\uc5b4\uc694.")
B.a03=new A.hO("\ubcf4\ud5d8\uc774 \ud3ec\ud568\ub3fc\ub3c4 \ud655\uc778\ud560 \uac83\uc774 \uc788\uc5b4\uc694","\uc7a5\uae30\ub80c\ud2b8\ub294 \ubcf4\ud1b5 \ub80c\ud130\uce74 \ud68c\uc0ac \ubcf4\ud5d8\uc73c\ub85c \uc0ac\uace0\ub97c \ucc98\ub9ac\ud574\uc694. \uadf8\ub807\ub2e4\uace0 \uc0ac\uace0 \ube44\uc6a9\uc774 \ud56d\uc0c1 0\uc6d0\uc778 \uac83\uc740 \uc544\ub2c8\uc5d0\uc694. \uc6b4\uc804\uc790 \ub098\uc774\xb7\ubc94\uc704, \ubcf4\uc7a5 \ud55c\ub3c4, \uc790\uae30\ubd80\ub2f4\uae08\uacfc \ubcf4\uc0c1 \uc81c\uc678 \uc870\uac74\uc744 \ud655\uc778\ud558\uc138\uc694. \ub9ac\uc2a4\ub294 \ubcc4\ub3c4 \uac00\uc785\ud560 \ubcf4\ud5d8\ub8cc\ub3c4 \ud568\uaed8 \uacc4\uc0b0\ud574\uc694.","\ubcf4\ud5d8 \ud3ec\ud568\uc774\ub77c\uace0 \ub05d\uc774 \uc544\ub2c8\ub124. \uc790\uae30\ubd80\ub2f4\uae08\ub3c4 \ubb3c\uc5b4\ubcf4\uc790.","\uc6b4\uc804\uc790 \uc870\uac74\xb7\ubcf4\uc7a5 \ubc94\uc704\xb7\uc790\uae30\ubd80\ub2f4\uae08\uc740 \uacc4\uc57d\ub9c8\ub2e4 \ub2ec\ub77c\uc694.")
B.a0a=new A.hO("\uacc4\uc57d \ub05d\ub0a0 \ub54c\uc758 \uc120\ud0dd\uae4c\uc9c0 \uc0b4\ud3b4\ubd10\uc694","\uc608\uc0c1 \uc8fc\ud589\uac70\ub9ac\uc640 \uc774\uc6a9 \uae30\uac04\uc744 \ubb34\ub9ac \uc5c6\uc774 \uc815\ud558\uc138\uc694. \uc57d\uc815 \uac70\ub9ac\ub97c \ub118\uae30\uac70\ub098 \uc911\ub3c4\uc5d0 \uacc4\uc57d\uc744 \ub05d\ub0b4\uba74 \ube44\uc6a9\uc774 \uc0dd\uae38 \uc218 \uc788\uc5b4\uc694. \ub9cc\uae30 \uc778\uc218\xb7\ubc18\ub0a9 \uac00\ub2a5 \uc5ec\ubd80\uc640 \uac01\uac01\uc758 \uc815\uc0b0 \ud56d\ubaa9\ub3c4 \uacc4\uc57d \uc804\uc5d0 \ud655\uc778\ud574 \ub450\uc138\uc694.","\uc5bc\ub9c8\ub098 \ud0c0\uace0, \uc5b8\uc81c\uae4c\uc9c0 \uc4f8\uc9c0 \uc815\ud55c \ub4a4 \uc120\ud0dd\ud560\ub798.","\ucd08\uacfc \uc8fc\ud589\uac70\ub9ac, \uc911\ub3c4\ud574\uc9c0, \ub9cc\uae30 \uc120\ud0dd \uc870\uac74\ub3c4 \ubbf8\ub9ac \ud655\uc778\ud574\uc694.")
B.a6S=s([B.a0b,B.a06,B.a03,B.a0a],t.ca)
B.a0e=new A.ys("first_car","\uccab\ucc28 \uac00\uc774\ub4dc","\uccab\ucc28\ub77c\uba74 \uc774\uac83\ub9cc \uc54c\uba74 \ub3fc\uc694","\ucc28\ub97c \uace0\ub974\uae30 \uc804\uc5d0 \ub0b4 \uc608\uc0b0\uacfc \uc774\uc6a9 \uc870\uac74\ubd80\ud130 \uc815\ud558\uba74 \ud6e8\uc52c \uc26c\uc6cc\uc838\uc694.",B.a94,B.a6S,"\uc120\ub0a9\uae08 0\uc6d0\uc740 \ub204\uad6c\ub098 \ubb34\uc870\uac74 \uac00\ub2a5\ud55c \uc870\uac74\uc774 \uc544\ub2c8\uc5d0\uc694. \uc2ec\uc0ac \uacb0\uacfc\uc640 \uacc4\uc57d \uc0c1\ud488\uc5d0 \ub530\ub77c \ucd08\uae30 \ube44\uc6a9\xb7\ubcf4\ud5d8 \uc870\uac74\xb7\ucd5c\uc885 \ub0a9\uc785\ub8cc\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc5b4\uc694.")
B.ah6=new A.iX("\ucc28\ub7c9 \uc0c1\ud0dc \xb7 \ucd08\uacfc \uc8fc\ud589\uac70\ub9ac \ub4f1 \uc815\uc0b0 \ud655\uc778","\ubc18\ub0a9")
B.ahm=new A.iX("\uc778\uc218\uac00 + \uc138\uae08\xb7\uc774\uc804 \ube44\uc6a9\uae4c\uc9c0 \ud655\uc778","\uc778\uc218")
B.a8Z=s([B.ah6,B.ahm],t.pT)
B.a_Z=new A.hO("\ub0b4 \uacc4\uc57d\uc5d0\uc11c \uac00\ub2a5\ud55c \uc120\ud0dd\ubd80\ud130 \ud655\uc778\ud574\uc694","\ub9cc\uae30\uc5d0 \uc778\uc218\xb7\ubc18\ub0a9\xb7\uc5f0\uc7a5 \uc911 \ubb34\uc5c7\uc774 \uac00\ub2a5\ud55c\uc9c0\ub294 \uc0c1\ud488\uacfc \uacc4\uc57d\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc694. \ucc98\uc74c \uacc4\uc57d\ud560 \ub54c \uc815\ud55c \uc778\uc218 \uc870\uac74\uacfc \ub9cc\uae30 \uc548\ub0b4\ub97c \uba3c\uc800 \ud655\uc778\ud558\uc138\uc694.","\uacc4\uc57d\uc774 \ub05d\ub098\uac00\ub124. \uacc4\uc18d \ud0c8\uae4c, \ub3cc\ub824\uc904\uae4c?","\uc778\uc218\xb7\ubc18\ub0a9\xb7\uc5f0\uc7a5 \uac00\ub2a5 \uc5ec\ubd80\ub294 \ub0b4 \uacc4\uc57d\ubd80\ud130 \ud655\uc778\ud574\uc694.")
B.a05=new A.hO("\ubc18\ub0a9\uc740 \ucc28 \uc0c1\ud0dc\uc640 \uc8fc\ud589\uac70\ub9ac\ub97c \ud655\uc778\ud574\uc694","\ucc28\ub97c \ub3cc\ub824\uc8fc\uba74 \ub418\uc9c0\ub9cc, \uc5b8\uc81c\ub098 \ucd94\uac00 \ube44\uc6a9 \uc5c6\uc774 \ub05d\ub098\ub294 \uac83\uc740 \uc544\ub2c8\uc5d0\uc694. \uc57d\uc815 \uc8fc\ud589\uac70\ub9ac \ucd08\uacfc, \ucc28\ub7c9 \uc190\uc0c1 \ub4f1 \uacc4\uc57d\uc0c1 \uc815\uc0b0 \ud56d\ubaa9\uacfc \ubc18\ub0a9 \uc7a5\uc18c\xb7\uc77c\uc815\uc744 \ud655\uc778\ud558\uc138\uc694.","\ubc18\ub0a9 \uc804\uc5d0 \uc8fc\ud589\uac70\ub9ac\uc640 \ucc28\ub7c9 \uc0c1\ud0dc\ub97c \uac19\uc774 \ud655\uc778\ud558\uc790.","\ucd08\uacfc \uc8fc\ud589\uac70\ub9ac\ub098 \ucc28\ub7c9 \uc190\uc0c1\uc5d0 \ub530\ub978 \uc815\uc0b0\uc774 \uc788\uc744 \uc218 \uc788\uc5b4\uc694.")
B.a00=new A.hO("\uc778\uc218\ub294 \ucc28 \uac12 \uc678\uc758 \ube44\uc6a9\ub3c4 \ub354\ud574\uc694","\ucc28\ub7c9\uc744 \ub0b4 \uba85\uc758\ub85c \uac00\uc838\uc624\ub824\uba74 \uacc4\uc57d\uc5d0\uc11c \uc815\ud55c \uc778\uc218\uac00 \uc678\uc5d0 \ucde8\ub4dd\uc138\uc640 \uc774\uc804 \ube44\uc6a9 \ub4f1\uc774 \ub4e4 \uc218 \uc788\uc5b4\uc694. \uc138\uae08\uc740 \ucc28\uc885\uacfc \uc801\uc6a9 \uc694\uac74\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c0\ubbc0\ub85c \ud55c \uac00\uc9c0 \uc138\uc728\ub85c \ub2e8\uc815\ud558\uc9c0 \ub9d0\uace0 \ucd5c\uc885 \uc778\uc218 \uacac\uc801\uc744 \ud655\uc778\ud558\uc138\uc694.","\uc778\uc218\uac00\ub9cc \ubcf4\uba74 \uc548 \ub418\ub124. \uc138\uae08\uacfc \uc774\uc804 \ube44\uc6a9\uae4c\uc9c0!","\uc138\uae08\uacfc \uc774\uc804 \ube44\uc6a9\uc740 \ucc28\uc885\uacfc \uc801\uc6a9 \uc694\uac74\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc838\uc694.")
B.a04=new A.hO("\ucd1d\ube44\uc6a9\uacfc \uc55e\uc73c\ub85c\uc758 \uacc4\ud68d\uc73c\ub85c \uacb0\uc815\ud574\uc694","\ube44\uc2b7\ud55c \uc5f0\uc2dd\xb7\uc8fc\ud589\uac70\ub9ac\xb7\uc0c1\ud0dc\uc758 \uc911\uace0\ucc28 \uc2dc\uc138\uc640 \ucd1d \uc778\uc218 \ube44\uc6a9\uc744 \ube44\uad50\ud574 \ubcf4\uc138\uc694. \uacc4\uc18d \ud0c8 \uae30\uac04\uacfc \uc608\uc0c1 \uc815\ube44\ube44\ub3c4 \uace0\ub824\ud574\uc57c \ud574\uc694. \uc2dc\uc138\uac00 \ub192\ub2e4\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \uc778\uc218\uac00 \ud56d\uc0c1 \uc720\ub9ac\ud55c \uac83\uc740 \uc544\ub2c8\uc5d0\uc694.","\uc55e\uc73c\ub85c \uc5bc\ub9c8\ub098 \ud0c8\uc9c0\uae4c\uc9c0 \uc0dd\uac01\ud574\uc11c \ub098\uc5d0\uac8c \ub9de\uac8c \uace0\ub974\uc790.","\ucc28\ub7c9 \uc2dc\uc138\ubfd0 \uc544\ub2c8\ub77c \uc55e\uc73c\ub85c\uc758 \uc774\uc6a9 \uacc4\ud68d\ub3c4 \uc911\uc694\ud574\uc694.")
B.a5c=s([B.a_Z,B.a05,B.a00,B.a04],t.ca)
B.a0d=new A.ys("end_of_term","\ub9cc\uae30 \uac00\uc774\ub4dc","\ub9cc\uae30\uc5d0 \uc778\uc218\ud560\uae4c, \ubc18\ub0a9\ud560\uae4c?","\uc815\ub2f5\uc740 \ud558\ub098\uac00 \uc544\ub2c8\uc5d0\uc694. \uacc4\uc57d \uc870\uac74\uacfc \uc55e\uc73c\ub85c \ucc28\ub97c \uc4f8 \uacc4\ud68d\uc744 \ud568\uaed8 \ubcf4\uc138\uc694.",B.a8Z,B.a5c,"\uc911\ub3c4\ud574\uc9c0\uc640 \ub9cc\uae30 \ubc18\ub0a9\uc740 \ub2e4\ub978 \uc808\ucc28\uc608\uc694. \ub9cc\uae30 \uc120\ud0dd \uac00\ub2a5 \uc5ec\ubd80, \uc778\uc218 \ube44\uc6a9, \ubc18\ub0a9 \uc815\uc0b0 \uae30\uc900\uc740 \uacc4\uc57d\uc11c\uac00 \uae30\uc900\uc774\uc5d0\uc694.")
B.agX=new A.iX("\ucc28\ub7c9\uc744 \uc0b4\ud3b4\ubcf4\uace0 \ub0b4 \uc870\uac74\uc73c\ub85c \uc608\uc0c1 \uae08\uc561 \ud655\uc778","\uc120\ud0dd \uc804")
B.agU=new A.iX("\ub0b4 \ucc28\uace0\uc5d0\uc11c \uc548\ub0b4\uc640 \uc9c4\ud589 \uc0c1\ud669 \ud655\uc778","\uc2e0\uccad \ud6c4")
B.a9O=s([B.agX,B.agU],t.pT)
B.a01=new A.hO("\ub9c8\uc74c\uc5d0 \ub4dc\ub294 \ucc28\ub7c9\uc744 \ucc3e\uc544\uc694","\ube0c\ub79c\ub4dc\uc640 \ucc28\uc885\uc73c\ub85c \ucc28\ub7c9\uc744 \ucc3e\uc544\ubcf4\uace0 \uc0c1\uc138 \ud654\uba74\uc5d0\uc11c \ud2b8\ub9bc\uacfc \uc635\uc158\uc744 \uc0b4\ud3b4\ubcf4\uc138\uc694. \ucc28\ub7c9 \uc774\ubbf8\uc9c0\uc640 \uc635\uc158 \uc81c\uacf5 \ubc94\uc704\ub294 \ubaa8\ub378\ub9c8\ub2e4 \ub2e4\ub97c \uc218 \uc788\uc73c\ub2c8 \uc2e4\uc81c \uc120\ud0dd \uac00\ub2a5\ud55c \ud56d\ubaa9\uc744 \uae30\uc900\uc73c\ub85c \ud655\uc778\ud574\uc694.","\uc6d0\ud558\ub294 \ucc28\ubd80\ud130 \ucc9c\ucc9c\ud788 \ucc3e\uc544\ubcfc\uae4c?","\uc0c1\uc138 \ud654\uba74\uc5d0\uc11c \uc2e4\uc81c \uc120\ud0dd \uac00\ub2a5\ud55c \ud2b8\ub9bc\uacfc \uc635\uc158\uc744 \uc0b4\ud3b4\ubd10\uc694.")
B.a_Y=new A.hO("\ub0b4 \uc870\uac74\uc73c\ub85c \uc608\uc0c1 \uae08\uc561\uc744 \ud655\uc778\ud574\uc694","\uacc4\uc57d \uae30\uac04, \uc5f0\uac04 \uc8fc\ud589\uac70\ub9ac, \uc120\ub0a9\uae08 \ub4f1 \uc870\uac74\uc744 \uc815\ud574\uc694. \ud45c\uc2dc\ub418\ub294 \uae08\uc561\uacfc \uc801\uc6a9 \uc870\uac74\uc744 \ud568\uaed8 \ud655\uc778\ud558\uc138\uc694. \uacac\uc801\uc744 \uc0b4\ud3b4\ubcf4\ub294 \uac83\ub9cc\uc73c\ub85c \uc2ec\uc0ac \uc2e0\uccad\uc774\ub098 \uacc4\uc57d\uc774 \uc644\ub8cc\ub418\uc9c0\ub294 \uc54a\uc544\uc694.","\uae30\uac04\uacfc \uc8fc\ud589\uac70\ub9ac\ub97c \ubc14\uafb8\ub2c8 \uc608\uc0c1 \uae08\uc561\ub3c4 \ub2ec\ub77c\uc9c0\ub124.","\uc608\uc0c1 \uacac\uc801\uc744 \ubcf4\ub294 \uac83\ub9cc\uc73c\ub85c \uc2ec\uc0ac\ub098 \uacc4\uc57d\uc774 \uc2dc\uc791\ub418\uc9c0\ub294 \uc54a\uc544\uc694.")
B.a07=new A.hO("\ud544\uc694\ud55c \uc0c1\ub2f4\uc73c\ub85c \uc0c1\uc138 \uc870\uac74\uc744 \ud655\uc778\ud574\uc694","\ub9ac\uc2a4 \ub4f1 \uc0c1\ub2f4\uc774 \ud544\uc694\ud55c \uc0c1\ud488\uc740 \uc120\ud0dd\ud55c \ucc28\ub7c9\uacfc \uc870\uac74\uc744 \ubc14\ud0d5\uc73c\ub85c \ub2f4\ub2f9\uc790\uac00 \uc548\ub0b4\ud574\uc694. \ucd5c\uc885 \uacac\uc801\uc758 \ud3ec\ud568 \ud56d\ubaa9\uacfc \uc2e0\uccad\uc5d0 \ud544\uc694\ud55c \ub0b4\uc6a9\uc744 \ud655\uc778\ud55c \ub4a4 \ub2e4\uc74c \uc808\ucc28\ub97c \uacb0\uc815\ud558\uc138\uc694.","\uad81\uae08\ud55c \uc870\uac74\uc740 \uc0c1\ub2f4\uc73c\ub85c \ud655\uc778\ud55c \ub2e4\uc74c \uacb0\uc815\ud558\uc790.","\ub9ac\uc2a4 \ub4f1 \uc0c1\ub2f4\uc774 \ud544\uc694\ud55c \uc0c1\ud488\uc740 \ub2f4\ub2f9\uc790 \uc548\ub0b4\ub85c \uc0c1\uc138 \uc870\uac74\uc744 \ud655\uc778\ud574\uc694.")
B.a08=new A.hO("\uc2e0\uccad \ub4a4\uc5d0\ub294 \ub0b4 \ucc28\uace0\uc5d0\uc11c \uc774\uc5b4\uac00\uc694","\ub85c\uadf8\uc778 \ud6c4 \ub0b4 \ucc28\uace0\uc5d0\uc11c \uc2e0\uccad\uacfc \uacac\uc801\uc758 \uc9c4\ud589 \uc0c1\ud669\uc744 \ud655\uc778\ud560 \uc218 \uc788\uc5b4\uc694. \ud544\uc694\ud55c \ub3d9\uc758\uc640 \uc11c\ub958 \uc81c\ucd9c, \uc2ec\uc0ac, \uacc4\uc57d\xb7\ucd9c\uace0 \uc548\ub0b4\ub294 \uc2e4\uc81c \uc9c4\ud589 \uc0c1\ud0dc\uc5d0 \ub530\ub77c \uc774\uc5b4\uc838\uc694. \uc2e0\uccad \uc811\uc218 \uc790\uccb4\uac00 \uc2b9\uc778\uc774\ub098 \uacc4\uc57d \uc644\ub8cc\ub97c \ub73b\ud558\uc9c0\ub294 \uc54a\uc544\uc694.","\ub2e4\uc74c\uc5d0 \ud574\uc57c \ud560 \uc77c\uc740 \ub0b4 \ucc28\uace0\uc5d0\uc11c \ud655\uc778\ud558\uba74 \ub418\uaca0\ub2e4.","\uc2e0\uccad \uc811\uc218\uac00 \uace7 \uc2b9\uc778\uc774\ub098 \uacc4\uc57d \uc644\ub8cc\ub97c \ub73b\ud558\uc9c0\ub294 \uc54a\uc544\uc694.")
B.a9k=s([B.a01,B.a_Y,B.a07,B.a08],t.ca)
